```cpp
const int DIRECTION_FORWARD = 1;
const int DIRECTION_BACKWARD = -1;

void cycleLEDs(int interval) {
  const int numOutputPins = sizeof(outPins) / sizeof(outPins[0]);
  static unsigned long lastChange = 0;
  static int currentIndex = 0;
  int nextLedIndex = 0;

  if (millis() >= lastChange + abs(interval)) {
    int ledDirection = (interval < 0) ? DIRECTION_BACKWARD : DIRECTION_FORWARD;

    // Update next LED index
    nextLedIndex = (currentIndex + ledDirection + numOutputPins) % numOutputPins;

    // Update LEDs
