**Chess Program in Python**

Below is a simplified implementation of a chess program in Python. It allows you to play against yourself. This implementation does not include any AI or advanced chess rules, but it covers the basic movements and captures.

### Code

```python
class Piece:
    def __init__(self, color, x, y):
        self.color = color
        self.x = x
        self.y = y

    def __str__(self):
        return f"{self.color} piece at ({self.x}, {self.y})"


class Pawn(Piece):
    def __init__(self, color, x, y):
        super().__init__(color, x, y)

    def __str__(self):
        return f"{self.color} pawn at ({self.x}, {self.y})"

    def is_valid_move(self, new_x, new_y):
        if self.color == "white":
            if self.y == 1 and new_y == 3 and new_x == self.x:
                return True
            elif new_y == self.y + 1 and new_x == self.x:
                return True
