Here's an example of how you can merge Word documents using the OpenXML SDK in C#. This function will take the first two pages from the first document, including its header, footer, and design, and then append the content from the second document.

```csharp
using System;
using System.IO;
using DocumentFormat.OpenXml;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;

public class WordDocumentMerger
{
    public void MergeDocuments(string sourceFile1, string sourceFile2, string outputFile)
    {
        // Open the first document
        using (WordprocessingDocument document1 = WordprocessingDocument.Open(sourceFile1, true))
        {
            // Open the second document
            using (WordprocessingDocument document2 = WordprocessingDocument.Open(sourceFile2, false))
            {
                // Get the main document parts
                MainDocumentPart mainDocumentPart1 = document1.MainDocumentPart;
                MainDocumentPart mainDocumentPart2 = document2.MainDocumentPart;

                // Get the styles and font table from the first document
                Styles styles = mainDocumentPart1.StyleDefinitionsPart.Styles;
                FontTable fontTable = mainDocumentPart1.FontTablePart.FontTable;

                // Add the styles and font table to the output document
                if (File.Exists(outputFile))
                {
                    File.Delete(outputFile);
                }

                File.Copy(sourceFile1, outputFile);

                // Open the output document
                using (WordprocessingDocument outputDocument = WordprocessingDocument.Open(outputFile, true))
                {
                    // Get the main document part
                    MainDocumentPart outputMainDocumentPart = outputDocument.MainDocumentPart;

                    // Get the sections from the second document
                    SectionProperties sectionProperties2 = mainDocumentPart2.Document.Body.Descendants<SectionProperties>().FirstOrDefault();

                    // Append the sections from the second document to the output document
                    foreach (SectionProperties section in outputMainDocumentPart.Document.Body.Descendants<SectionProperties>())
                    {
                        if (sectionProperties2 != null)
                        {
                            section.AppendChild(sectionProperties2.CloneNode(true));
                        }
                    }

                    // Get the paragraphs from the second document
                    var paragraphs2 = mainDocumentPart2.Document.Body.Descendants<Paragraph>();

                    // Get the header and footer parts from the first document
                    HeaderPart headerPart1 = mainDocumentPart1.HeaderParts.FirstOrDefault();
                    FooterPart footerPart1 = mainDocumentPart1.FooterParts.FirstOrDefault();

                    // Add the header and footer parts to the output document
                    if (headerPart1 != null)
                    {
                        outputMainDocumentPart.AddPart(headerPart1);
                    }

                    if (footerPart1 != null)
                    {
                        outputMainDocumentPart.AddPart(footerPart1);
                    }

                    // Get the paragraphs from the first document
                    var paragraphs1 = mainDocumentPart1.Document.Body.Descendants<Paragraph>();

                    // Remove the last two paragraphs from the first document
                    int paragraphCount = paragraphs1.Count();
                    if (paragraphCount > 2)
                    {
                        for (int i = paragraphCount - 1; i >= paragraphCount - 2; i--)
                        {
                            paragraphs1.ElementAt(i).Remove();
                        }
                    }

                    // Append the paragraphs from the second document to the output document
                    foreach (Paragraph paragraph in paragraphs2)
                    {
                        outputMainDocumentPart.Document.Body.AppendChild(paragraph.CloneNode(true));
                    }

                    // Save the output document
                    outputMainDocumentPart.Document.Save();
                }
            }
        }
    }
}
```

You can use the `WordDocumentMerger` class to merge Word documents like this:

```csharp
class Program
{
    static void Main()
    {
        WordDocumentMerger merger = new WordDocumentMerger();
        merger.MergeDocuments("document1.docx", "document2.docx", "output.docx");
    }
}
```

Please note that this code does not handle all possible scenarios, such as duplicate styles or font tables, and it assumes that the documents have the same number of sections and header/footer parts. You may need to modify it to suit your specific requirements.

Also, make sure to install the OpenXML SDK NuGet package in your project:

```
Install-Package DocumentFormat.OpenXml
```

