**Chunk.gd**
```gdscript
extends Spatial

class_name Chunk

var chunk_size = 16
var blocks := {}

func _init(pos: Vector3):
    for x in range(chunk_size):
        for y in range(chunk_size):
            for z in range(chunk_size):
                var block_type = _get_block_type(pos + Vector3(x, y, z))
                if block_type != 0:
                    add_block(pos + Vector3(x, y, z), block_type)

func _get_block_type(pos: Vector3) -> int:
    # Simple noise-based block generation
    var noise = OpenSimplexNoise.new()
    noise.seed = pos.x + pos.z * 57
    noise.octaves = 6
    noise.period = 20.0
    noise.persistence = 0.8
    noise.lacunarity = 2.0
    var value = noise.get_noise_3d(pos.x, pos.y, pos.z)
    if value > 0.5:
        return 1  # Dirt block
    elif value > 0.2:
        return 2  # Stone block
    return 0  # Air block

func add_block(pos: Vector3, block_type: int):
    var block = Block.new(pos, block_type)
    add_child(block)
    blocks[pos] = block

func remove_block(pos: Vector3):
    if pos in blocks:
        var block = blocks[pos]
        remove_child(block)
        blocks.erase(pos)
