**Old-School Raycasting in GLSL**
=====================================

This example demonstrates a simple raycasting technique using GLSL shaders. The code generates a 3D scene with a grid of cubes and a moving camera.

**Vertex Shader**
---------------

```glsl
#version 330 core

// Input vertex data
layout(location = 0) in vec3 aPosition;
layout(location = 1) in vec2 aTexCoord;

// Uniforms
uniform mat4 model;
uniform mat4 view;
uniform mat4 projection;

// Output to fragment shader
out vec2 TexCoord;

void main()
{
    gl_Position = projection * view * model * vec4(aPosition, 1.0);
    TexCoord = aTexCoord;
}
```

**Fragment Shader**
-----------------

```glsl
#version 330 core

// Input from vertex shader
in vec2 TexCoord;

// Uniforms
uniform sampler2D textureMap;
uniform int screenWidth;
uniform int screenHeight;
uniform vec3 cameraPos;
uniform vec3 cameraDir;
uniform vec3 gridPos;
uniform float gridSize;

// Output to screen
out vec4 FragColor;

// Raycasting function
float raycast(vec2 uv)
{
    // Calculate ray direction
    vec3 rayDir = vec3(uv * 2.0 - 1.0, 1.0);
    rayDir = normalize(rayDir);

    // Initialize ray position
    vec3 rayPos = cameraPos;

    // Raymarch the grid
    for (int i = 0; i < 100; i++)
    {
        // Check if we're inside the grid
        vec3 gridCoord = floor((rayPos - gridPos) / gridSize);
        if (gridCoord.x >= 0 && gridCoord.x < 10 &&
            gridCoord.y >= 0 && gridCoord.y < 10 &&
            gridCoord.z >= 0 && gridCoord.z < 10)
        {
            // Check if we're hitting a cube
            if (mod(gridCoord.x + gridCoord.y + gridCoord.z, 2.0) == 0)
            {
                return float(i) / 100.0;
            }
        }

        // Move the ray forward
        rayPos += rayDir * gridSize / 5.0;
    }

    // If we didn't hit anything, return a default value
    return 1.0;
}

void main()
{
    // Calculate UV coordinates
    vec2 uv = TexCoord;

    // Perform raycasting
    float depth = raycast(uv);

    // Map depth to color
    FragColor = vec4(vec3(depth), 1.0);
}
```

**Example Usage**
-----------------

