class ReverbEffect {
    private var nativeReverb: ReverbEffectNative? = null

    fun init(sampleRate: Int, numChannels: Int) {
        nativeReverb = ReverbEffectNative()
        nativeReverb?.initReverb(sampleRate, numChannels)
    }

