```cpp
#include <highfive/H5File.hpp>
#include <highfive/H5Group.hpp>
#include <highfive/H5CompoundType.hpp>

// Define the struct
struct Data {
    double v[3];
    int n;
};

int main() {
    // Create a file
    HighFive::File file("data.h5", HighFive::File::ReadWrite | HighFive::File::Create | HighFive::File::Truncate);

    // Create a compound datatype
    HighFive::CompoundType compound_type(sizeof(Data));
    compound_type.insertMember("v", HOFFSET(Data, v), HighFive::FloatType());
    compound_type.insertMember("n", HOFFSET(Data, n), HighFive::IntType());

    // Create a dataset with the compound datatype
    HighFive::DataSet dataset = file.createDataSet("data", compound_type);

    // You can now write data to the dataset
    Data data;
    data.v[0] = 1.0;
    data.v[1] = 2.0;
    data.v[2] = 3.0;
    data.n = 10;
    dataset.write(&data);

    return 0;
}
```

