        this.destinationPort = (packet[2] << 8) + packet[3];
        this.sequenceNumber = (packet[4] << 24) + (packet[5] << 16) + (packet[6] << 8) + packet[7];
        this.acknowledgementNumber = (packet[8] << 24) + (packet[9] << 16) + (packet[10] << 8) + packet[11];
        this.dataOffset = (packet[12] >> 4) * 4;
        this.reserved = packet[12] & 0x0F;
        this.flags = {
