            ack: (packet[13] & 0x10) !== 0,
            psh: (packet[13] & 0x08) !== 0,
            rst: (packet[13] & 0x04) !== 0,
            syn: (packet[13] & 0x02) !== 0,
            fin: (packet[13] & 0x01) !== 0
        };
        this.window = (packet[14] << 8) + packet[15];
        this.checksum = (packet[16] << 8) + packet[17];
        this.urgentPointer = (packet[18] << 8) + packet[19];

        // Extract options and data
