        return this.data;
    }
}

class TcpConnection {
    private localSequenceNumber: number;
    private remoteSequenceNumber: number;
    private localAcknowledgementNumber: number;
    private remoteAcknowledgementNumber: number;
    private localPort: number;
    private remotePort: number;

    constructor(localPort: number, remotePort: number) {
        this.localPort = localPort;
        this.remotePort = remotePort;
        this.localSequenceNumber = Math.floor(Math.random() * 1000);
        this.remoteSequenceNumber = 0;
        this.localAcknowledgementNumber = 0;
        this.remoteAcknowledgementNumber = 0;
    }

    public handlePacket(packet: TcpPacket): TcpPacket {
        // Handle packet based on flags
        if (packet.getFlags().syn) {
            // Handle SYN packet
            this.remoteSequenceNumber = packet.getSequenceNumber();
            this.remoteAcknowledgementNumber = packet.getAcknowledgementNumber();

            // Send SYN-ACK packet
            return this.createSynAckPacket(packet.getSequenceNumber());
        } else if (packet.getFlags().ack) {
            // Handle ACK packet
            this.remoteSequenceNumber = packet.getSequenceNumber();
            this.remoteAcknowledgementNumber = packet.getAcknowledgementNumber();

            // Check if the packet is in sequence
            if (packet.getSequenceNumber() === this.localAcknowledgementNumber + 1) {
                // Update local acknowledgement number
                this.localAcknowledgementNumber = packet.getSequenceNumber();
            }
        } else {
            // Handle other packets
            // This is a simplified example and doesn't handle all possible scenarios
        }

        return null;
    }

    private createSynAckPacket(sequenceNumber: number): TcpPacket {
        // Create a SYN-ACK packet
        const packet = new Uint8Array(20); // Minimal TCP packet size
        packet[0] = this.localPort >> 8;
        packet[1] = this.localPort & 0xFF;
        packet[2] = this.remotePort >> 8;
        packet[3] = this.remotePort & 0xFF;
        packet[4] = this.localSequenceNumber >> 24;
        packet[5] = (this.localSequenceNumber >> 16) & 0xFF;
        packet[6] = (this.localSequenceNumber >> 8) & 0xFF;
        packet[7] = this.localSequenceNumber & 0xFF;
        packet[8] = sequenceNumber >> 24;
        packet[9] = (sequenceNumber >> 16) & 0xFF;
        packet[10] = (sequenceNumber >> 8) & 0xFF;
        packet[11] = sequenceNumber & 0xFF;
        packet[12] = 0x50; // Data offset
        packet[13] = 0x12; // Flags (SYN-ACK)
        packet[14] = this.window >> 8;
        packet[15] = this.window & 0xFF;
        packet[16] = this.checksum >> 8;
        packet[17] = this.checksum & 0xFF;
        packet[18] = 0x00;
        packet[19] = 0x00;

        // Create a TcpPacket object
        const tcpPacket = new TcpPacket(packet);
        return tcpPacket;
    }

    private checksum(packet: Uint8Array): number {
        // Calculate the checksum
        // This is a simplified example and doesn't handle all possible scenarios
        let sum = 0;
        for (let i = 0; i < packet.length; i += 2) {
            sum += (packet[i] << 8) + packet[i + 1];
        }
        return sum;
    }
}
```

