Create a `TodoList.js` component to render the list of to-dos:

```javascript
// TodoList.js
import React, { useState, useEffect } from 'react';
import Todo from './Todo';

const TodoList = () => {
    const [todos, setTodos] = useState([]);
    const [newTodo, setNewTodo] = useState({ title: '', description: '' });

    useEffect(() => {
        fetch('/api/todos')
            .then(response => response.json())
            .then(data => setTodos(data));
    }, []);

    const handleSubmit = (event) => {
        event.preventDefault();
        fetch('/api/todos', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(newTodo),
        })
            .then(response => response.json())
            .then(data => setTodos([...todos, data]))
            .then(() => setNewTodo({ title: '', description: '' }));
    };

    const updateTodo = (id, completed) => {
        fetch(`/api/todos/${id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed }),
        })
            .then(response => response.json())
            .then(data => {
                const updatedTodos = todos.map((todo) => {
                    if (todo.id === id) {
                        return data;
                    }
                    return todo;
                });
                setTodos(updatedTodos);
            });
    };

    const deleteTodo = (id) => {
        fetch(`/api/todos/${id}`, { method: 'DELETE' })
            .then(() => {
                const updatedTodos = todos.filter((todo) => todo.id !== id);
                setTodos(updatedTodos);
            });
    };

    return (
        <div>
            <h1>Todo List</h1>
            <form onSubmit={handleSubmit}>
                <input
                    type="text"
                    value={newTodo.title}
                    onChange={(event) => setNewTodo({ ...newTodo, title: event.target.value })}
                    placeholder="Title"
                />
                <input
                    type="text"
                    value={newTodo.description}
                    onChange={(event) => setNewTodo({ ...newTodo, description: event.target.value })}
                    placeholder="Description"
                />
                <button type="submit">Create Todo</button>
            </form>
            {todos.map((todo) => (
                <Todo key={todo.id} todo={todo} updateTodo={updateTodo} deleteTodo={deleteTodo} />
            ))}
        </div>
    );
};

export default TodoList;
```

Finally, update the `App.js` file to render the `TodoList` component:

```javascript
// App.js
import React from 'react';
import TodoList from './TodoList';

function App() {
    return (
        <div>
            <TodoList />
        </div>
    );
}

export default App;
```

Start the server and the React app:

```bash
node server.js
npm start
```

