void conv_layer(activation_t *input, activation_t *output, weight_t *weights, int num_inputs, int num_outputs) {
    #pragma HLS PIPELINE
    for (int i = 0; i < num_outputs; i++) {
        activation_t sum = 0;
        for (int j = 0; j < num_inputs; j++) {
            sum += input[j] * weights[i * num_inputs + j];
        }
        output[i] = sum;
