### Step 3: Fetch data with `@tanstack/vue-query` and update Pinia store

Now, you can use `@tanstack/vue-query` to fetch data from `/get_session` and select specific keys in the response to update in the Pinia store.

```javascript
// api/session.js
import { useQueryClient } from '@tanstack/vue-query';
import { useSessionStore } from '../stores/session';
import axios from 'axios';

export const getSession = async () => {
  const queryClient = useQueryClient();
  const sessionStore = useSessionStore();

  const { data } = await axios.get('/get_session');

  // Select specific keys from the response
  const { id, name } = data;

  // Update the Pinia store
  sessionStore.$patch({ id, name });

  // Return the data
  return data;
};

export const useGetSessionQuery = () => {
  return useQuery(
    ['session'], // key for caching
    getSession,
    {
      // Options for the query
