% Define the grid size
dx = 0.01;           % m
dy = 0.01;           % m
dt = 0.01;           % s

% Create the grid
x = 0:dx:tank_length;
y = 0:dy:tank_width;
[X, Y] = meshgrid(x, y);

% Define the wave parameters
gravity = 9.81;      % m/s^2
depth = 0.1;         % m

% Initialize the wave height and velocity
wave_height = zeros(size(X));
wave_velocity_x = zeros(size(X));
wave_velocity_y = zeros(size(X));

% Define the time parameters
time = 0;
end_time = 5;        % s
time_step = 0;

% Create a figure to display the wave
figure;
while time < end_time
    % Update the wave height and velocity using the finite difference method
    wave_height_new = 2 * wave_height - wave_height(:,:,1) + gravity * dt^2 * ( ...
        (wave_height(:,2:end) - 2 * wave_height(:,1:end-1) + wave_height(:,1:end-2)) / dx^2 + ...
        (wave_height(2:end,:) - 2 * wave_height(1:end-1,:) + wave_height(1:end-2,:)) / dy^2);
    wave_height_new(:,1) = wave_height(:,1) + wind_speed * dt;  % Apply wind pressure at the left boundary
    wave_height_new(:,end) = wave_height(:,end) - wind_speed * dt;  % Apply wind pressure at the right boundary
    wave_height_new(1,:) = wave_height(1,:);  % No flow at the bottom boundary
    wave_height_new(end,:) = wave_height(end,:);  % No flow at the top boundary
    wave_height = wave_height_new;

    % Update the wave velocity
    wave_velocity_x = (wave_height(:,2:end) - wave_height(:,1:end-1)) / dx;
    wave_velocity_y = (wave_height(2:end,:) - wave_height(1:end-1,:)) / dy;

    % Display the wave
    surf(X, Y, wave_height);
    colormap cool;
    shading flat;
    lighting phong;
    axis equal;
    axis([0 tank_length 0 tank_width -0.1 0.1]);
    title(['Time: ', num2str(time), ' s']);
    drawnow;

    % Update the time
    time = time + dt;
    time_step = time_step + 1;
end
```

This script creates a 3D surface plot of the wave height at each time step, with the wind blowing from the left to the right. The wave height is initialized to zero, and the wind pressure is applied at the left and right boundaries. The wave velocity is calculated using the finite difference method. The script runs until the end time is reached.

Note that this is a simplified model and does not take into account many factors that can affect the wave motion, such as viscosity, surface tension, and non-linear effects.

### Recursive JSON Search Function

Here's a JavaScript function that takes a JSON object and an entity key as input, and returns an array containing the value of the key and its location in the JSON object.

```javascript
/**
 * Recursively searches a JSON object for a given entity key.
 *
 * @param {Object} json - The JSON object to search.
 * @param {string} key - The entity key to search for.
 * @param {string} [path=''] - The current path in the JSON object (used for recursion).
 * @returns {Array|null} An array containing the value of the key and its location, or null if the key is not found.
 */
function recursiveJsonSearch(json, key, path = '') {
  // Initialize the result variable to null
  let result = null;

  // Iterate over the keys in the JSON object
  for (const k in json) {
    // Construct the current path
    const currentPath = path ? `${path}.${k}` : k;

    // Check if the current key matches the entity key
    if (k === key) {
      // If it matches, update the result variable with the value and location
      result = [json[k], currentPath];
      break;
    }

    // Check if the current value is an object
    if (typeof json[k] === 'object') {
      // If it's an object, recursively call the function with the current value and path
      result = recursiveJsonSearch(json[k], key, currentPath);

      // If the recursive call returns a result, break out of the loop
      if (result) {
        break;
      }
    }
  }

  // Return the result
  return result;
}
```

