using System.Timers;

namespace NetworkTrafficDecoder
{
    public partial class Service1 : ServiceBase
    {
        private readonly NetworkCaptureAdapter _adapter;
        private readonly PacketDecoder _decoder;
        private Timer _timer;

        public Service1()
        {
            _adapter = new NetworkCaptureAdapter("\\Device\\NPF_{device-name}");
            _decoder = new PacketDecoder();

            _adapter.PacketArrived += (sender, e) =>
            {
